<div><em><strong>এই চালুনি ব্যবহার করে ময়দা বা অন্য শুষ্ক উপাদানগুলোকে ছেঁকে ফেলা যায়, ফলে এদের মধ্যে থাকা ময়লা, গুটিকা বা বড় কণা সহজেই আলাদা করা যায়। এটি বেকিংয়ে সমানভাবে ময়দার মিশ্রণ তৈরি করতে সাহায্য করে।</strong></em></div>
